from pathlib import Path
import json,csv,sys,hashlib
sys.path.insert(0,str(Path('tmp/chart-deps').resolve()))
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np
root=Path('tmp/advanced');before=json.loads((root/'metrics-round2.json').read_text());after={r['name']:r for r in json.loads((root/'metrics-round3-current.json').read_text())}
labels=['Woven pattern','Damaged JPEG','Dense engraving','Soft transparency','CAD grid','Tiny circuit labels','Astronaut photograph','Cat photograph','Coffee photograph','600 colored shapes']
fig,axes=plt.subplots(2,2,figsize=(15,12),layout='constrained');fig.set_facecolor('#f8faf7')
specs=[('mae','Image fidelity','Mean absolute RGB error · lower is better',1),('paths','Output complexity','Paths · log scale',1),('bytes','SVG size','MiB',1024**2),('ms','Conversion time','Seconds · median of 3 local runs',1000)]
for ax,(key,title,xlabel,divisor) in zip(axes.flat,specs):
    y=np.arange(len(before));b=[r[key]/divisor for r in before];a=[after[r['name']][key]/divisor for r in before];ax.set_facecolor('#f8faf7');ax.barh(y-.18,b,.34,label='Previous',color='#cc8d59');ax.barh(y+.18,a,.34,label='Updated',color='#54816c');ax.set_yticks(y,labels);ax.invert_yaxis();ax.set_title(title,loc='left',fontweight='bold',fontsize=14,pad=12);ax.set_xlabel(xlabel,fontsize=10);ax.grid(axis='x',alpha=.15);ax.set_axisbelow(True);ax.spines[['top','right','left']].set_visible(False)
    if key=='paths':ax.set_xscale('log');ax.set_xlim(20,max(b+a)*2)
    else:ax.set_xlim(0,max(b+a)*1.22)
    for i,(v,w) in enumerate(zip(b,a)):
        for value,pos in [(v,i-.18),(w,i+.18)]:ax.text(value*1.025 if key=='paths' else value+max(b+a)*.012,pos,f'{value:,.0f}' if key=='paths' else f'{value:.2f}',fontsize=8,va='center',color='#34483d')
axes[0,0].legend(frameon=False,loc='lower right');fig.suptitle('Outline Studio · Real photographs and advanced stress tests',fontsize=20,fontweight='bold',color='#24372e');fig.savefig('advanced-performance-chart.png',dpi=140,facecolor=fig.get_facecolor());fig.savefig('advanced-performance-chart.svg',facecolor=fig.get_facecolor());plt.close(fig)
records=[]
for suite in ['quality','complex','advanced']:
    r=Path('tmp')/suite;b={row['name']:row for row in json.loads((r/'metrics-round2.json').read_text())};a=json.loads((r/'metrics-round3-current.json').read_text())
    for row in a:
        old=b[row['name']];assert row['mae']<=old['mae']+.01,(suite,row['name'],'white regression');assert row['mae_black']<=old['mae_black']+.01,(suite,row['name'],'black regression');records.append(dict(suite=suite,image=row['name'],before_error=old['mae'],after_error=row['mae'],before_black_error=old['mae_black'],after_black_error=row['mae_black'],before_paths=old['paths'],after_paths=row['paths'],before_bytes=old['bytes'],after_bytes=row['bytes'],before_ms=old['ms'],after_ms=row['ms']))
with open('advanced-performance-results.csv','w',newline='')as f:w=csv.DictWriter(f,fieldnames=records[0].keys());w.writeheader();w.writerows(records)
rows=['# Advanced tracing improvements and tests','', '26 paired cases: 9 simple fixtures, 7 complex procedural images, and 10 new advanced cases. Three advanced cases are real photographs from scikit-image (astronaut, Chelsea, coffee); see IMAGE-SOURCES.md for attribution, source URLs, and preparation. All photographs were proportionally limited to 512 pixels on the longest edge. Generated cases reach 1024×640.', '', 'Compared against the exact engine from the previous completed turn, retained in scripts/quality-round2.cjs. Current default controls were kept the same. Adaptive mode may now choose 64 colors for color-rich images instead of 32; these results assess the whole pipeline, not a single algorithm at identical palette size.', '', '## Changes', '', '- Real artwork classification flag replaces a name that collided with the built-in Array.flat method. Non-logo inputs no longer inherit logo-only recovery by accident.', '- Small and narrow regions retain their actual boundary coverage.', '- Exact-color line art uses original grid boundaries and tighter fitting; Smooth mode retains the approximation option.', '- Color-rich illustrations automatically receive up to 64 colors. Manual color mode remains available.', '- Semi-transparent colors are assigned using their appearance over light and dark backgrounds.', '- Large SVGs use one delegated selection handler instead of a listener per path.', '', '## Measurement', '', 'SVG vector paths are exported to PDF and rasterized with PDFium at source dimensions. Errors are mean absolute RGB differences on white and black backgrounds, not percentage accuracy scores. Timing is the median of three local Node runs for preparation, conversion, and SVG generation. Timing excludes the browser preview, exporting, downloads, and network. Runs were not performed on an otherwise idle, isolated machine, so small timing differences should not be treated as definitive speed gains.', '', 'All 26 cases show no regression above 0.01 in mean RGB error on either background. This does not guarantee improvement at every pixel or in every perceptual metric. Photos remain vector approximations: fur, faces, fine texture, smooth gradients, and feathered alpha still show simplification or banding. Higher fidelity often costs more paths, bytes, and time.', '', '| Case | Error before | Error after | Paths before | Paths after |','|---|---:|---:|---:|---:|']
for r in records:rows.append(f"| {r['image']} | {r['before_error']} | {r['after_error']} | {r['before_paths']:,} | {r['after_paths']:,} |")
rows+=['', 'Photograph sources: https://scikit-image.org/docs/stable/api/skimage.data', '', 'SHA-256 of downloaded originals:']
for p in sorted((root/'source').glob('*.png')):rows.append(f'- {p.name}: {hashlib.sha256(p.read_bytes()).hexdigest()}')
rows+=['', 'Reproduction: run scripts/advanced-fixtures.py; set QUALITY_ROOT=tmp/advanced; run scripts/quality-benchmark.cjs round2 and round3-current; run scripts/quality-score.py for each variant with tmp/advanced. Repeat those two variant runs for tmp/quality and tmp/complex, then run scripts/advanced-report.py. See earlier fixture scripts for generation. Python requires Pillow, pypdfium2, numpy, and matplotlib.']
Path('ADVANCED-PERFORMANCE-REPORT.md').write_text('\n'.join(rows),encoding='utf-8');print(f'Validated {len(records)} pairs; saved advanced charts, results, and report.')
